[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>UK Retail Fuel Price Trend Analysis — February 2026</title>
<style>
  :root {
    --bg: #f8f9fb;
    --surface: #ffffff;
    --border: #e2e6ed;
    --text: #1a202c;
    --text-muted: #64748b;
    --accent: #1e40af;
    --accent-light: #dbeafe;
    --success: #065f46;
    --success-bg: #d1fae5;
    --warn: #92400e;
    --warn-bg: #fef3c7;
    --danger: #991b1b;
    --danger-bg: #fee2e2;
    --e10: #2563eb;
    --b7s: #7c3aed;
    --e5: #059669;
    --b7p: #dc2626;
    --hvo: #d97706;
    --b10: #6b7280;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 14px;
  }
  .page-header {
    background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 60%, #2563eb 100%);
    color: white;
    padding: 48px 60px 40px;
  }
  .page-header .badge {
    display: inline-block;
    background: rgba(255,255,255,0.18);
    border: 1px solid rgba(255,255,255,0.3);
    border-radius: 20px;
    padding: 3px 12px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    margin-bottom: 16px;
  }
  .page-header h1 { font-size: 32px; font-weight: 700; margin-bottom: 10px; line-height: 1.2; }
  .page-header p { font-size: 15px; opacity: 0.85; max-width: 680px; margin-bottom: 20px; }
  .header-meta { display: flex; gap: 32px; font-size: 12px; opacity: 0.75; }
  .header-meta span { display: flex; align-items: center; gap: 6px; }

  .container { max-width: 1160px; margin: 0 auto; padding: 40px 32px; }

  /* KPI Bar */
  .kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-bottom: 40px; }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--accent);
  }
  .kpi-card .kpi-value { font-size: 28px; font-weight: 700; color: var(--accent); line-height: 1; margin-bottom: 4px; }
  .kpi-card .kpi-label { font-size: 12px; color: var(--text-muted); font-weight: 500; }
  .kpi-card .kpi-sub { font-size: 11px; color: var(--text-muted); margin-top: 6px; }

  /* Sections */
  section { margin-bottom: 48px; }
  .section-header { border-left: 4px solid var(--accent); padding-left: 14px; margin-bottom: 20px; }
  .section-header h2 { font-size: 20px; font-weight: 700; color: var(--text); }
  .section-header p { font-size: 13px; color: var(--text-muted); margin-top: 4px; }
  .section-num { font-size: 11px; font-weight: 700; color: var(--accent); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 4px; }

  /* Cards */
  .card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 20px;
  }
  .card h3 { font-size: 15px; font-weight: 600; margin-bottom: 14px; color: var(--text); }

  /* Tables */
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  thead th {
    background: #f1f5f9;
    color: var(--text-muted);
    font-weight: 600;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 10px 12px;
    text-align: right;
    border-bottom: 2px solid var(--border);
  }
  thead th:first-child { text-align: left; }
  tbody td { padding: 10px 12px; text-align: right; border-bottom: 1px solid var(--border); }
  tbody td:first-child { text-align: left; font-weight: 600; }
  tbody tr:hover { background: #f8fafc; }
  tbody tr:last-child td { border-bottom: none; }

  /* Fuel type pill */
  .fuel-pill {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 12px; font-weight: 600; padding: 2px 10px;
    border-radius: 12px; white-space: nowrap;
  }
  .pill-e10 { background: #dbeafe; color: #1e40af; }
  .pill-b7s { background: #ede9fe; color: #5b21b6; }
  .pill-e5 { background: #d1fae5; color: #065f46; }
  .pill-b7p { background: #fee2e2; color: #991b1b; }
  .pill-hvo { background: #fef3c7; color: #92400e; }
  .pill-b10 { background: #f1f5f9; color: #374151; }

  .dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }

  /* Two-col grid */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }

  /* Alert boxes */
  .alert {
    border-radius: 8px;
    padding: 14px 16px;
    font-size: 13px;
    margin-bottom: 16px;
    display: flex;
    gap: 10px;
  }
  .alert-icon { font-size: 16px; flex-shrink: 0; margin-top: 1px; }
  .alert-warn { background: var(--warn-bg); color: var(--warn); border-left: 3px solid #f59e0b; }
  .alert-info { background: var(--accent-light); color: var(--accent); border-left: 3px solid #3b82f6; }
  .alert-success { background: var(--success-bg); color: var(--success); border-left: 3px solid #10b981; }
  .alert-danger { background: var(--danger-bg); color: var(--danger); border-left: 3px solid #ef4444; }

  /* Bar chart rows */
  .bar-row { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
  .bar-label { width: 100px; font-size: 12px; font-weight: 600; color: var(--text); flex-shrink: 0; }
  .bar-track { flex: 1; background: #f1f5f9; border-radius: 4px; height: 22px; overflow: hidden; position: relative; }
  .bar-fill { height: 100%; border-radius: 4px; transition: width 0.3s; display: flex; align-items: center; padding-left: 8px; }
  .bar-val { font-size: 11px; font-weight: 700; color: white; white-space: nowrap; }
  .bar-val-outside { font-size: 11px; font-weight: 600; color: var(--text-muted); margin-left: 8px; white-space: nowrap; }

  /* SVG Charts */
  svg { overflow: visible; }

  /* Key findings */
  .finding {
    display: flex; gap: 16px;
    padding: 18px 20px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    margin-bottom: 14px;
  }
  .finding-num {
    width: 32px; height: 32px; min-width: 32px;
    border-radius: 50%;
    background: var(--accent);
    color: white;
    font-size: 14px;
    font-weight: 700;
    display: flex; align-items: center; justify-content: center;
  }
  .finding-body h4 { font-size: 14px; font-weight: 700; margin-bottom: 4px; }
  .finding-body p { font-size: 13px; color: var(--text-muted); }
  .finding-tag {
    display: inline-block;
    font-size: 10px; font-weight: 700;
    text-transform: uppercase; letter-spacing: 0.05em;
    padding: 2px 8px; border-radius: 10px;
    background: var(--accent-light); color: var(--accent);
    margin-bottom: 6px;
  }

  /* Footnote */
  .footnote { font-size: 11px; color: var(--text-muted); margin-top: 10px; }

  /* Divider */
  hr { border: none; border-top: 1px solid var(--border); margin: 32px 0; }

  footer {
    background: #1e293b;
    color: #94a3b8;
    padding: 24px 60px;
    font-size: 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  @media (max-width: 900px) {
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .two-col, .three-col { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- ============================================================ PAGE HEADER -->
<div class="page-header">
  <div class="badge">Government Policy Analysis</div>
  <h1>UK Retail Fuel Price Trend Analysis</h1>
  <p>A comprehensive examination of retail fuel pricing patterns across UK forecourts based on government-mandated open data, assessing market competitiveness, pricing transparency, and retailer reporting behaviour.</p>
  <div class="header-meta">
    <span>&#128197; Data Period: Feb–Apr 2026</span>
    <span>&#128202; 50,000 price observations</span>
    <span>&#9981; 7,373 unique stations</span>
    <span>&#128337; Generated: April 2026</span>
  </div>
</div>

<div class="container">

<!-- ============================================================ KPI STRIP -->
<div class="kpi-grid" style="margin-top: 32px;">
