          <td>9,308</td><td>161.3</td><td>160.9</td><td>13.0</td><td>120.0</td><td>213.0</td>
        </tr>
        <tr>
          <td><span class="fuel-pill pill-b7p"><span class="dot" style="background:#dc2626;"></span>B7_PREMIUM</span></td>
          <td>7,560</td><td>185.8</td><td>187.9</td><td>18.6</td><td>100.0</td><td>265.9</td>
        </tr>
        <tr>
          <td><span class="fuel-pill pill-hvo"><span class="dot" style="background:#d97706;"></span>HVO</span></td>
          <td>89</td><td>187.4</td><td>189.9</td><td>17.5</td><td>144.0</td><td>226.9</td>
        </tr>
